import math

def psi(expected, actual):
    return sum((a - e) * math.log(a / e) for e, a in zip(expected, actual))

print(round(psi([0.5, 0.3, 0.2], [0.4, 0.3, 0.3]), 3))   # 0.063 - stable
print(round(psi([0.6, 0.4], [0.3, 0.7]), 3))              # 0.376 - major shift

